import sqlite3

DATABASE_FILE_PATH = "lms.db"


def delete_course_discussion_thread(thread_id: int, course_id: int) -> dict:
    database_connection = sqlite3.connect(DATABASE_FILE_PATH)
    try:
        matching_thread_row = database_connection.execute(
            "SELECT id FROM discussion_threads WHERE id = ? AND course_id = ?",
            (thread_id, course_id),
        ).fetchone()

        if matching_thread_row is None:
            return {"deleted": False, "error": "Thread not found in this course"}

        deleted_replies_cursor = database_connection.execute(
            "DELETE FROM discussion_replies WHERE thread_id = ?",
            (thread_id,),
        )
        database_connection.execute(
            "DELETE FROM discussion_threads WHERE id = ?",
            (thread_id,),
        )
        database_connection.commit()

        return {
            "deleted": True,
            "thread_id": thread_id,
            "replies_deleted": deleted_replies_cursor.rowcount,
        }
    except sqlite3.Error as database_error:
        database_connection.rollback()
        return {"deleted": False, "error": str(database_error)}
    finally:
        database_connection.close()
